/* ================================================================== */
/* Hand-added: A6XX A2D 2D-blitter registers, bitfield encoders and    */
/* field enums.  Offsets / bit positions / enum values transcribed      */
/* verbatim from Mesa freedreno/registers/adreno/{a6xx,a6xx_enums,      */
/* adreno_pm4,adreno_common}.xml (A6XX variants).  These drive the      */
/* solid-fill / copy / scale / rotate blit emitted by adreno_2d.c via   */
/* PKT4 register writes + a CP_BLIT trigger (see mesa fd6_blitter.cc    */
/* emit_blit_setup / emit_blit_dst / emit_blit_src / clear_surface_     */
/* setup).  Register offsets here are the raw PKT4 register indices     */
/* (NOT the *4 MMIO word indices used by adreno_gpu_read/write).        */
/* ================================================================== */

/* --- register offsets --- */
#define REG_A6XX_RB_A2D_BLT_CNTL                                       0x00008c00u
#define REG_A6XX_RB_A2D_PIXEL_CNTL                                     0x00008c01u
#define REG_A6XX_RB_A2D_DEST_BUFFER_INFO                               0x00008c17u
#define REG_A6XX_RB_A2D_DEST_BUFFER_BASE                               0x00008c18u  /* reg64 waddress align64: lo, hi@0x8c19 */
#define REG_A6XX_RB_A2D_DEST_BUFFER_PITCH                              0x00008c1au  /* [0:15] shr6 */
#define REG_A6XX_RB_A2D_CLEAR_COLOR_DW0                                0x00008c2cu
#define REG_A6XX_RB_A2D_CLEAR_COLOR_DW1                                0x00008c2du
#define REG_A6XX_RB_A2D_CLEAR_COLOR_DW2                                0x00008c2eu
#define REG_A6XX_RB_A2D_CLEAR_COLOR_DW3                                0x00008c2fu
#define REG_A6XX_RB_DBG_ECO_CNTL                                       0x00008e04u  /* blit = bit24; valid mask 0xfffffeff */
#define REG_A6XX_RB_CCU_CNTL                                           0x00008e07u
#define REG_A6XX_SP_A2D_OUTPUT_INFO                                    0x0000acc0u
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_INFO                             0x0000b4c0u
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_SIZE                             0x0000b4c1u  /* WIDTH[0:14] HEIGHT[15:29] */
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_BASE                             0x0000b4c2u  /* reg64 address align16: lo, hi@0xb4c3 */
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_PITCH                            0x0000b4c4u  /* UNK0[0:8] PITCH[9:23] shr6 */
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_FLAG_BASE                        0x0000b4cau  /* reg64 address align16 */
#define REG_A6XX_TPL1_A2D_SRC_TEXTURE_FLAG_PITCH                       0x0000b4ccu  /* [0:7] shr6 */

/* --- field enums (a6xx_enums.xml / a6xx.xml / adreno_pm4.xml) --- */
#define FMT6_A8_UNORM                                                  0x02u
#define FMT6_8_UNORM                                                   0x03u
#define FMT6_8_8_8_8_UNORM                                             0x30u  /* == PIPE_FORMAT_B8G8R8A8_UNORM */
#define R2D_UNORM8                                                     0x0u
#define R2D_UNORM8_SRGB                                                0x1u
#define TILE6_LINEAR                                                   0x0u
#define A3XX_COLOR_SWAP_WZYX                                           0x0u  /* identity for LINEAR */
#define A3XX_COLOR_SWAP_WXYZ                                           0x1u
#define A3XX_COLOR_SWAP_ZYXW                                           0x2u
#define A3XX_COLOR_SWAP_XYZW                                           0x3u
#define A6XX_ROTATE_0                                                  0x0u
#define A6XX_ROTATE_90                                                 0x1u
#define A6XX_ROTATE_180                                                0x2u
#define A6XX_ROTATE_270                                                0x3u
#define OUTPUT_IFMT_2D_FLOAT                                           0x0u
#define PIXEL_OP_DISABLED                                              0x0u
#define PIXEL_OP_BLENDING                                              0x1u
#define PIXEL_OP_ROP                                                   0x3u
/* adreno_rb_blend_factor (adreno_common.xml) - shared by the 3D RB and the
   A2D RB_A2D_PIXEL_CNTL blend fields. */
#define A3XX_FACTOR_ZERO                                               0x0u
#define A3XX_FACTOR_ONE                                                0x1u
#define A3XX_FACTOR_SRC_ALPHA                                          0x6u
#define A3XX_FACTOR_ONE_MINUS_SRC_ALPHA                                0x7u
/* a3xx_rb_blend_opcode (adreno_common.xml): out = dst*dstf OP src*srcf. */
#define A3XX_BLEND_DST_PLUS_SRC                                        0x0u
#define CCU_CACHE_SIZE_FULL                                            0x0u
#define A6XX_BLIT_OP_SCALE                                             0x3u   /* CP_BLIT_0.OP[0:3] */
/* CP_SET_MARKER payload: MARKER_MODE=SET_RENDER_MODE(0,bit8) |
   USES_GMEM(0,bit4) | MODE=RM6_BLIT2DSCALE(12,[0:3]) == 0x0c. */
#define A6XX_SET_MARKER_BLIT2DSCALE                                    0x0cu
/* CP_SET_MARKER payload for the COMPUTE render mode: MODE=RM6_COMPUTE
   (8, adreno_pm4.xml enum rm6_mode) in [0:3], SET_RENDER_MODE(bit8)=0,
   USES_GMEM(bit4)=0, SHADER_USES_RT=0  == 0x08.  turnip emits this via
   tu_set_render_mode<CHIP>(cs, {RM6_COMPUTE}) immediately before the CS
   NDRANGE/CP_EXEC_CS dispatch (tu_cmd_buffer.cc:9609). */
#define A6XX_SET_MARKER_COMPUTE                                        0x08u

/* --- bitfield encoders --- */
/* a6xx_reg_xy: X[0:13], Y[16:29] (GRAS_A2D_DEST_TL/BR, SCISSOR_TL/BR). */
#define A6XX_REG_XY(x, y) \
	(((((uint32_t)(x))) & 0x3fffu) | ((((uint32_t)(y)) & 0x3fffu) << 16))
/* GRAS_A2D_SRC_XMIN/XMAX/YMIN/YMAX: field low=8 high=24 type=int. */
#define A6XX_A2D_SRC_COORD(v)        ((((uint32_t)(v)) & 0x1ffffu) << 8)
/* a6xx_a2d_blt_cntl (RB_A2D_BLT_CNTL / GRAS_A2D_BLT_CNTL). */
#define A2D_BLT_ROTATE(r)            (((uint32_t)(r)) & 0x7u)          /* [0:2]   */
#define A2D_BLT_SOLID_COLOR          (1u << 7)                         /* [7]     */
#define A2D_BLT_COLOR_FORMAT(f)      ((((uint32_t)(f)) & 0xffu) << 8)  /* [8:15]  */
#define A2D_BLT_SCISSOR              (1u << 16)                        /* [16]    */
#define A2D_BLT_MASK(m)              ((((uint32_t)(m)) & 0xfu) << 20)  /* [20:23] */
#define A2D_BLT_IFMT(i)              ((((uint32_t)(i)) & 0x7u) << 24)  /* [24:26] */
/* a6xx_a2d_dest_buffer_info (RB_A2D_DEST_BUFFER_INFO). */
#define A2D_DEST_COLOR_FORMAT(f)     (((uint32_t)(f)) & 0xffu)         /* [0:7]   */
#define A2D_DEST_TILE_MODE(t)        ((((uint32_t)(t)) & 0x3u) << 8)   /* [8:9]   */
#define A2D_DEST_COLOR_SWAP(s)       ((((uint32_t)(s)) & 0x3u) << 10)  /* [10:11] */
/* RB_A2D_DEST_BUFFER_PITCH: [0:15] shr6. */
#define A2D_DEST_PITCH(p)            (((((uint32_t)(p)) >> 6)) & 0xffffu)
/* a6xx_a2d_src_texture_info (TPL1_A2D_SRC_TEXTURE_INFO). */
#define A2D_SRC_COLOR_FORMAT(f)      (((uint32_t)(f)) & 0xffu)         /* [0:7]   */
#define A2D_SRC_TILE_MODE(t)         ((((uint32_t)(t)) & 0x3u) << 8)   /* [8:9]   */
#define A2D_SRC_COLOR_SWAP(s)        ((((uint32_t)(s)) & 0x3u) << 10)  /* [10:11] */
#define A2D_SRC_FILTER(f)            ((((uint32_t)(f)) & 0x1u) << 16)  /* [16]    */
#define A2D_SRC_UNK20                (1u << 20)                        /* [20]    */
#define A2D_SRC_UNK22                (1u << 22)                        /* [22]    */
/* TPL1_A2D_SRC_TEXTURE_SIZE: WIDTH[0:14], HEIGHT[15:29]. */
#define A2D_SRC_SIZE(w, h) \
	((((uint32_t)(w)) & 0x7fffu) | ((((uint32_t)(h)) & 0x7fffu) << 15))
/* TPL1_A2D_SRC_TEXTURE_PITCH: PITCH[9:23] shr6. */
#define A2D_SRC_PITCH(p)             ((((((uint32_t)(p)) >> 6)) & 0x7fffu) << 9)
/* a6xx_sp_a2d_output_info (SP_A2D_OUTPUT_INFO). */
#define A2D_OUT_IFMT_TYPE(t)         ((((uint32_t)(t)) & 0x3u) << 1)   /* [1:2]   */
#define A2D_OUT_COLOR_FORMAT(f)      ((((uint32_t)(f)) & 0xffu) << 3)  /* [3:10]  */
#define A2D_OUT_MASK(m)              ((((uint32_t)(m)) & 0xfu) << 12)  /* [12:15] */
/* RB_A2D_PIXEL_CNTL (0x8c01): PIXEL_OP[0:1], COLOR_SRC_FACTOR[6:10],
   COLOR_BLEND_OP[11:13], COLOR_DST_FACTOR[14:18], ALPHA_SRC_FACTOR[19:23],
   ALPHA_BLEND_OP[24:26], ALPHA_DST_FACTOR[27:31]. */
#define A2D_PIXEL_OP(op)             (((uint32_t)(op)) & 0x3u)         /* [0:1]   */
#define A2D_PIXEL_COLOR_SRC(f)       ((((uint32_t)(f)) & 0x1fu) << 6)  /* [6:10]  */
#define A2D_PIXEL_COLOR_OP(o)        ((((uint32_t)(o)) & 0x7u) << 11)  /* [11:13] */
#define A2D_PIXEL_COLOR_DST(f)       ((((uint32_t)(f)) & 0x1fu) << 14) /* [14:18] */
#define A2D_PIXEL_ALPHA_SRC(f)       ((((uint32_t)(f)) & 0x1fu) << 19) /* [19:23] */
#define A2D_PIXEL_ALPHA_OP(o)        ((((uint32_t)(o)) & 0x7u) << 24)  /* [24:26] */
#define A2D_PIXEL_ALPHA_DST(f)       ((((uint32_t)(f)) & 0x1fu) << 27) /* [27:31] */
/* Standard source-over (per-pixel src alpha): out.rgb = src.rgb*src.a +
   dst.rgb*(1-src.a); out.a = src.a + dst.a*(1-src.a).  Reproduces the EwokOS
   CPU reference (g2d_blend_argb_scalar / x86_blt_alpha_px with global alpha
   0xff, whose alpha lane dst.a + (255-dst.a)*sa == src.a + dst.a*(1-src.a)). */
#define A2D_PIXEL_SRC_OVER \
	(A2D_PIXEL_OP(PIXEL_OP_BLENDING) | \
	 A2D_PIXEL_COLOR_SRC(A3XX_FACTOR_SRC_ALPHA) | \
	 A2D_PIXEL_COLOR_OP(A3XX_BLEND_DST_PLUS_SRC) | \
	 A2D_PIXEL_COLOR_DST(A3XX_FACTOR_ONE_MINUS_SRC_ALPHA) | \
	 A2D_PIXEL_ALPHA_SRC(A3XX_FACTOR_ONE) | \
	 A2D_PIXEL_ALPHA_OP(A3XX_BLEND_DST_PLUS_SRC) | \
	 A2D_PIXEL_ALPHA_DST(A3XX_FACTOR_ONE_MINUS_SRC_ALPHA))

/* ================================================================== */
/* Hand-added: A6XX compute-shader (CS) dispatch field encoders, the    */
/* CP_LOAD_STATE6 state-upload encoders and the a6xx_tex_const buffer-  */
/* view (MEMOBJ) descriptor encoders.  Offsets / bit positions / enum   */
/* values transcribed verbatim from Mesa                                */
/* freedreno/registers/gen/{a6xx,a6xx_descriptors,adreno_pm4}.xml.h     */
/* (A6XX variants); the emit ORDER these drive is turnip tu_shader.cc   */
/* (tu6_emit_xs MESA_SHADER_COMPUTE / tu6_emit_cs_config /              */
/* tu6_emit_xs_constants) + tu_pipeline.cc (tu6_emit_xs_config) +       */
/* tu_cmd_buffer.cc (the A6XX-aligned SP_CS_NDRANGE + CP_EXEC_CS path). */
/* The register OFFSETS for every CS register below already appear in   */
/* the block above (SP_CS_*, SP_UPDATE_CNTL, SP_PS_WAVE_CNTL,           */
/* HLSQ_CS_CTRL_REG1); this section only adds the bitfield encoders +   */
/* enums the A2D-only subset did not need.  Register offsets here are   */
/* the raw PKT4 register indices (NOT the *4 MMIO word indices).        */
/* ================================================================== */

/* --- enums --- */
/* enum a6xx_threadsize (SP_CS_CNTL_0 / *_WGE_CNTL / SP_PS_WAVE_CNTL). */
#define A6XX_THREAD64                                                  0x0u
#define A6XX_THREAD128                                                 0x1u
/* enum a6xx_const_ram_mode (SP_CS_CNTL_1 / HLSQ_CS_CTRL_REG1), from constlen. */
#define A6XX_CONSTLEN_128                                              0x0u
#define A6XX_CONSTLEN_192                                              0x1u
#define A6XX_CONSTLEN_256                                              0x2u
#define A6XX_CONSTLEN_512                                              0x3u
/* regid(63,0) == INVALID_REG (ir3/instr-a3xx.h): the "unused" const/reg id. */
#define A6XX_INVALID_REGID                                             0xfcu
/* enum a6xx_tex_type (a6xx_enums.xml): a raw buffer (SSBO) view. */
#define A6XX_TEX_BUFFER                                                0x4u
/* enum a6xx_tex_swiz (a6xx_enums.xml): identity component order. */
#define A6XX_TEX_SWIZ_X                                                0x0u
#define A6XX_TEX_SWIZ_Y                                                0x1u
#define A6XX_TEX_SWIZ_Z                                                0x2u
#define A6XX_TEX_SWIZ_W                                                0x3u
/* enum a6xx_color_fmt: R32_UINT, the format turnip binds an SSBO as
   (fdl6_buffer_view_init(PIPE_FORMAT_R32_UINT), fd6_format_table). */
#define FMT6_32_UINT                                                   0x4bu  /* 75 */

/* --- SP_UPDATE_CNTL (0xbb08): flag the CS state blocks dirty. --- */
#define A6XX_SP_UPDATE_CNTL_CS_STATE                                   0x00000020u
#define A6XX_SP_UPDATE_CNTL_CS_UAV                                     0x00000040u
#define A6XX_SP_UPDATE_CNTL_CS_SHARED_CONST                            0x00080000u

/* --- SP_CS_CNTL_0 (0xa9b0).  reg footprints are 7-bit: 6 bits in the
   main field + 1 LSB bit (FULLREGFOOTPRINT_LSB@27 / HALFREGFOOTPRINT_LSB@30),
   matching the generated a6xx_sp_cs_cntl_0 packing. --- */
#define A6XX_SP_CS_CNTL_0_HALFREGFOOTPRINT(v) \
	(((((uint32_t)(v)) & 0x3fu) << 1) | ((((uint32_t)(v)) & 0x40u) << 24))
#define A6XX_SP_CS_CNTL_0_FULLREGFOOTPRINT(v) \
	(((((uint32_t)(v)) & 0x3fu) << 7) | ((((uint32_t)(v)) & 0x40u) << 21))
#define A6XX_SP_CS_CNTL_0_BRANCHSTACK(v)       ((((uint32_t)(v)) & 0x7fu) << 13)  /* [13:19] */
#define A6XX_SP_CS_CNTL_0_THREADSIZE(v)        ((((uint32_t)(v)) & 0x1u) << 20)   /* [20]    */
#define A6XX_SP_CS_CNTL_0_COMPUTERRMODEEN      (1u << 22)                         /* [22]    */
#define A6XX_SP_CS_CNTL_0_EARLYPREAMBLE        (1u << 23)                         /* [23]    */
#define A6XX_SP_CS_CNTL_0_MERGEDREGS           (1u << 31)                         /* [31]    */

/* --- SP_CS_CNTL_1 (0xa9b1) --- */
#define A6XX_SP_CS_CNTL_1_SHARED_SIZE(v)       ((((uint32_t)(v)) & 0x1fu) << 0)   /* [0:4]  */
#define A6XX_SP_CS_CNTL_1_CONSTANTRAMMODE(m)   ((((uint32_t)(m)) & 0x3u) << 5)    /* [5:6]  */

/* --- HLSQ_CS_CTRL_REG1 (0xb9d0): same field layout as SP_CS_CNTL_1
   (written too on A690, which has_lpac). --- */
#define A6XX_HLSQ_CS_CTRL_REG1_SHARED_SIZE(v)      ((((uint32_t)(v)) & 0x1fu) << 0)
#define A6XX_HLSQ_CS_CTRL_REG1_CONSTANTRAMMODE(m)  ((((uint32_t)(m)) & 0x3u) << 5)

/* --- SP_CS_CONFIG (0xa9bb) --- */
#define A6XX_SP_CS_CONFIG_ENABLED                (1u << 8)                        /* [8]     */
#define A6XX_SP_CS_CONFIG_NTEX(v)                ((((uint32_t)(v)) & 0xffu) << 9)  /* [9:16]  */
#define A6XX_SP_CS_CONFIG_NSAMP(v)               ((((uint32_t)(v)) & 0x1fu) << 17) /* [17:21] */
#define A6XX_SP_CS_CONFIG_NUAV(v)                ((((uint32_t)(v)) & 0x7fu) << 22) /* [22:28] */

/* --- SP_CS_CONST_CONFIG (0xb987): CONSTLEN is shr2 (units of 4 vec4). --- */
#define A6XX_SP_CS_CONST_CONFIG_CONSTLEN(v)      (((((uint32_t)(v)) >> 2)) & 0xffu)
#define A6XX_SP_CS_CONST_CONFIG_ENABLED          (1u << 8)

/* --- SP_CS_NDRANGE_0 (0xb990): kerneldim + local size.  A6XX carries the
   local size here; SP_CS_NDRANGE_7 (localsize) is A7XX+ only. --- */
#define A6XX_SP_CS_NDRANGE_0_KERNELDIM(v)        ((((uint32_t)(v)) & 0x3u) << 0)   /* [0:1]   */
#define A6XX_SP_CS_NDRANGE_0_LOCALSIZEX(v)       ((((uint32_t)(v)) & 0x3ffu) << 2) /* [2:11]  */
#define A6XX_SP_CS_NDRANGE_0_LOCALSIZEY(v)       ((((uint32_t)(v)) & 0x3ffu) << 12)/* [12:21] */
#define A6XX_SP_CS_NDRANGE_0_LOCALSIZEZ(v)       ((((uint32_t)(v)) & 0x3ffu) << 22)/* [22:31] */

/* --- SP_CS_CONST_CONFIG_0 (0xb997) and SP_CS_WIE_CNTL_0 (0xa9c2) share this
   layout (sysval const/reg ids). --- */
#define A6XX_SP_CS_CONSTID_WGID(v)               ((((uint32_t)(v)) & 0xffu) << 0)
#define A6XX_SP_CS_CONSTID_WGSIZE(v)             ((((uint32_t)(v)) & 0xffu) << 8)
#define A6XX_SP_CS_CONSTID_WGOFFSET(v)           ((((uint32_t)(v)) & 0xffu) << 16)
#define A6XX_SP_CS_CONSTID_LOCALID(v)            ((((uint32_t)(v)) & 0xffu) << 24)
/* --- SP_CS_WGE_CNTL (0xb998) and SP_CS_WIE_CNTL_1 (0xa9c3) share this. --- */
#define A6XX_SP_CS_WGE_LINEARLOCALIDREGID(v)     ((((uint32_t)(v)) & 0xffu) << 0)
#define A6XX_SP_CS_WGE_THREADSIZE(v)             ((((uint32_t)(v)) & 0x1u) << 9)
/* --- SP_PS_WAVE_CNTL (0xb980) --- */
#define A6XX_SP_PS_WAVE_CNTL_THREADSIZE(v)       ((((uint32_t)(v)) & 0x1u) << 0)

/* --- CS private (spill/stack) memory.  Each field is a size in a fixed
   power-of-two unit; the generated encoders shift and assert the low bits
   are zero, so the values passed here MUST be unit-aligned (the pvtmem
   layout in adreno_3d.c aligns them: 512 / 4096 / 2048). --- */
#define A6XX_SP_CS_PVT_MEM_PARAM_MEMSIZEPERITEM(v)   (((((uint32_t)(v)) >> 9)) & 0xffu)     /* 512-B  */
#define A6XX_SP_CS_PVT_MEM_SIZE_TOTALPVTMEMSIZE(v)   (((((uint32_t)(v)) >> 12)) & 0x3ffffu) /* 4096-B */
#define A6XX_SP_CS_PVT_MEM_SIZE_PERWAVEMEMLAYOUT     (1u << 31)
#define A6XX_SP_CS_PVT_MEM_STACK_OFFSET_OFFSET(v)    (((((uint32_t)(v)) >> 11)) & 0x7ffffu) /* 2048-B */

/* --- CP_LOAD_STATE6 (adreno_pm4.xml): the state-upload packet payload.
   opcode CP_LOAD_STATE6_FRAG (0x34) is used for the COMPUTE stage
   (tu6_stage2opcode).  Word 0 packs dst_off/type/src/block/num_unit;
   words 1/2 carry the external source address (lo shr2, hi). --- */
/* enum a6xx_state_type */
#define A6XX_ST6_SHADER                                              0x0u
#define A6XX_ST6_CONSTANTS                                           0x1u
#define A6XX_ST6_UBO                                                 0x2u
#define A6XX_ST6_UAV                                                 0x3u
/* enum a6xx_state_src */
#define A6XX_SS6_DIRECT                                              0x0u
#define A6XX_SS6_BINDLESS                                            0x1u
#define A6XX_SS6_INDIRECT                                            0x2u
/* enum a6xx_state_block (the CS-relevant entries) */
#define A6XX_SB6_CS_TEX                                              0x5u
#define A6XX_SB6_CS_SHADER                                           0xdu
#define A6XX_SB6_UAV                                                 0xeu
#define A6XX_SB6_CS_UAV                                              0xfu
#define A6XX_CP_LOAD_STATE6_0_DST_OFF(v)         ((((uint32_t)(v)) & 0x3fffu) << 0)   /* [0:13]  */
#define A6XX_CP_LOAD_STATE6_0_STATE_TYPE(t)      ((((uint32_t)(t)) & 0x3u) << 14)     /* [14:15] */
#define A6XX_CP_LOAD_STATE6_0_STATE_SRC(s)       ((((uint32_t)(s)) & 0x3u) << 16)     /* [16:17] */
#define A6XX_CP_LOAD_STATE6_0_STATE_BLOCK(b)     ((((uint32_t)(b)) & 0xfu) << 18)     /* [18:21] */
#define A6XX_CP_LOAD_STATE6_0_NUM_UNIT(n)        ((((uint32_t)(n)) & 0x3ffu) << 22)   /* [22:31] */
#define A6XX_CP_LOAD_STATE6_1_EXT_SRC_ADDR(v)    ((((uint32_t)(v)) >> 2 << 2) & 0xfffffffcu)
#define A6XX_CP_LOAD_STATE6_2_EXT_SRC_ADDR_HI(v) ((uint32_t)(v))
/* A6XX_UBO_1_SIZE (a6xx_descriptors.xml): a UBO descriptor's size in vec4s. */
#define A6XX_UBO_1_SIZE(v)                       ((((uint32_t)(v)) & 0x7fffu) << 17)

/* --- a6xx_tex_const (MEMOBJ) buffer-view descriptor words.  Built exactly
   like fdl6_buffer_view_init() (fdl/fd6_view.cc) for a linear R32_UINT SSBO:
   word0 tile/swap/fmt/miplvls/swiz, word1 width|height (element count split
   at 15 bits), word2 structsize|startoffset|type=BUFFER, word4/5 the 64-byte
   aligned base iova (raw lo/hi; the base is pre-aligned so the shr5 field
   equals the raw value).  FDL6_TEX_CONST_DWORDS == 16 (64 bytes). --- */
#define A6XX_TEX_CONST_DWORDS                                        16u
#define A6XX_TEX_MEMOBJ_0_TILE_MODE(v)           ((((uint32_t)(v)) & 0x3u) << 0)
#define A6XX_TEX_MEMOBJ_0_SWIZ_X(v)              ((((uint32_t)(v)) & 0x7u) << 4)
#define A6XX_TEX_MEMOBJ_0_SWIZ_Y(v)              ((((uint32_t)(v)) & 0x7u) << 7)
#define A6XX_TEX_MEMOBJ_0_SWIZ_Z(v)              ((((uint32_t)(v)) & 0x7u) << 10)
#define A6XX_TEX_MEMOBJ_0_SWIZ_W(v)              ((((uint32_t)(v)) & 0x7u) << 13)
#define A6XX_TEX_MEMOBJ_0_MIPLVLS(v)             ((((uint32_t)(v)) & 0xfu) << 16)
#define A6XX_TEX_MEMOBJ_0_FMT(f)                 ((((uint32_t)(f)) & 0xffu) << 22)
#define A6XX_TEX_MEMOBJ_0_SWAP(s)                ((((uint32_t)(s)) & 0x3u) << 30)
#define A6XX_TEX_MEMOBJ_1_WIDTH(v)               ((((uint32_t)(v)) & 0x7fffu) << 0)
#define A6XX_TEX_MEMOBJ_1_HEIGHT(v)              ((((uint32_t)(v)) & 0x7fffu) << 15)
#define A6XX_TEX_MEMOBJ_2_STRUCTSIZETEXELS(v)    ((((uint32_t)(v)) & 0xfffu) << 4)
#define A6XX_TEX_MEMOBJ_2_STARTOFFSETTEXELS(v)   ((((uint32_t)(v)) & 0x3fu) << 16)
#define A6XX_TEX_MEMOBJ_2_TYPE(t)                ((((uint32_t)(t)) & 0x7u) << 29)

#endif /* ADRENO_A6XX_REGS_H */
